#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')


def load_json(path):
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)


def load_csv(path):
    with open(path, 'r', encoding='utf-8', newline='') as f:
        return list(csv.DictReader(f))


def as_float(value):
    return float(str(value).strip())


def as_int(value):
    return int(float(str(value).strip()))


def money(value):
    return round(float(value), 2)


def manifest_campaigns(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        if isinstance(data.get('campaigns'), list):
            return data['campaigns']
        campaigns = []
        for region in data.get('regions', []):
            campaigns.extend(region.get('campaigns', []))
        return campaigns
    raise TypeError('campaign_manifest.json must contain a JSON array or object')


def main():
    manifest = load_json(ROOT / 'campaign_manifest.json')
    crate_rows = load_csv(ROOT / 'crate_cost.csv')
    billing_rows = load_csv(ROOT / 'billing.csv')
    override_rows = load_csv(ROOT / 'location_overrides.csv')
    suspension_rows = load_csv(ROOT / 'suspensions.csv')

    crate_cost_by_tier = {
        row['crate_tier']: as_float(row['crate_cost_usd'])
        for row in crate_rows
    }

    held_campaigns = {
        row['campaign_id']
        for row in suspension_rows
        if row.get('suspension_status') == 'hold'
    }

    campaigns = [
        c for c in manifest_campaigns(manifest)
        if c.get('analysis_flag') == 'review' and c.get('campaign_id') not in held_campaigns
    ]

    # Latest valid approved location override by numeric revision.
    best_override_by_campaign = {}
    for row in override_rows:
        if row.get('state') != 'approved':
            continue
        revision = str(row.get('revision', '')).strip()
        active_clinics = str(row.get('active_clinics', '')).strip()
        if not revision or not active_clinics:
            continue
        campaign_id = row['campaign_id']
        revision_num = as_int(revision)
        current = best_override_by_campaign.get(campaign_id)
        if current is None or revision_num > current['revision']:
            best_override_by_campaign[campaign_id] = {
                'revision': revision_num,
                'active_clinics': as_int(active_clinics),
            }

    output_campaigns = []
    total_margin_6 = 0.0
    total_margin_12 = 0.0

    for campaign in campaigns:
        labels = {campaign.get('campaign_name')}
        labels.update(campaign.get('alias_labels') or [])
        active_billing = [
            row for row in billing_rows
            if row.get('status') == 'active' and row.get('campaign_label') in labels
        ]
        if not active_billing:
            raise ValueError(f"No active billing row found for {campaign['campaign_id']}")
        billing = max(active_billing, key=lambda row: row.get('cycle_tag', ''))
        payment = as_float(billing['payment_per_dispatch_per_clinic_usd'])

        override = best_override_by_campaign.get(campaign['campaign_id'])
        active_clinics = override['active_clinics'] if override else as_int(campaign['default_active_clinics'])

        crate_tier = campaign['crate_tier']
        if crate_tier not in crate_cost_by_tier:
            raise ValueError(f"No crate cost found for tier {crate_tier!r}")
        crate_cost = crate_cost_by_tier[crate_tier]

        drug_cost_per_1000 = as_float(campaign['drug_cost_per_1000_doses_usd'])
        doses_per_day = as_float(campaign['doses_per_day'])

        scenarios = {}
        margins = {}
        for key, days_per_dispatch, dispatches_per_year in [
            ('6_day', 6, 60),
            ('12_day', 12, 30),
        ]:
            annual_revenue = payment * active_clinics * dispatches_per_year
            annual_drug_cost = (
                drug_cost_per_1000
                * active_clinics
                * doses_per_day
                * days_per_dispatch
                * dispatches_per_year
                / 1000
            )
            annual_crate_cost = crate_cost * dispatches_per_year
            annual_margin = annual_revenue - annual_drug_cost - annual_crate_cost
            scenarios[key] = {
                'days_per_dispatch': days_per_dispatch,
                'dispatches_per_year': dispatches_per_year,
                'annual_revenue': money(annual_revenue),
                'annual_drug_cost': money(annual_drug_cost),
                'annual_crate_cost': money(annual_crate_cost),
                'annual_margin': money(annual_margin),
            }
            margins[key] = annual_margin

        difference = margins['12_day'] - margins['6_day']
        total_margin_6 += margins['6_day']
        total_margin_12 += margins['12_day']

        output_campaigns.append({
            'campaign_id': campaign['campaign_id'],
            'campaign_name': campaign['campaign_name'],
            'matched_billing_label': billing['campaign_label'],
            'billing_cycle_tag': billing['cycle_tag'],
            'payment_per_dispatch_per_clinic_usd': money(payment),
            'active_clinics': active_clinics,
            'crate_tier': crate_tier,
            'crate_cost_usd': money(crate_cost),
            'drug_cost_per_1000_doses_usd': money(drug_cost_per_1000),
            'doses_per_day': doses_per_day,
            'six_day': scenarios['6_day'],
            'twelve_day': scenarios['12_day'],
            'difference': money(difference),
        })

    output_campaigns.sort(key=lambda c: c['campaign_id'])

    total_difference = total_margin_12 - total_margin_6
    absolute_total_difference = abs(total_difference)
    decision = 'move_to_12_day' if absolute_total_difference < 11000 else 'keep_6_day'
    justification = (
        f"Absolute total margin difference is ${money(absolute_total_difference):,.2f}, "
        f"compared with the $11,000.00 threshold."
    )

    result = {
        'campaigns': output_campaigns,
        'totals': {
            'total_margin_6_day': money(total_margin_6),
            'total_margin_12_day': money(total_margin_12),
            'total_difference': money(total_difference),
            'absolute_total_difference': money(absolute_total_difference),
        },
        'recommendation': {
            'decision': decision,
            'justification': justification,
        },
    }

    with open(ROOT / 'vaxcrate_analysis.json', 'w', encoding='utf-8') as f:
        json.dump(result, f, indent=2)
        f.write('\n')

    summary_lines = [
        '# VaxCrate Dispatch Margin Summary',
        f"Total 6-day margin (USD): ${money(total_margin_6):,.2f}",
        f"Total 12-day margin (USD): ${money(total_margin_12):,.2f}",
        f"Absolute difference (USD): ${money(absolute_total_difference):,.2f}",
        f"Decision: {decision}",
        justification,
    ]
    with open(ROOT / 'vaxcrate_summary.md', 'w', encoding='utf-8') as f:
        f.write('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()

