                'annual_margin': money(annual_margin),
            }
            margins[key] = annual_margin

        difference = margins['12_day'] - margins['6_day']
        total_margin_6 += margins['6_day']
        total_margin_12 += margins['12_day']

        output_campaigns.append({
            'campaign_id': campaign['campaign_id'],
            'campaign_name': campaign['campaign_name'],
            'matched_billing_label': billing['campaign_label'],
            'billing_cycle_tag': billing['cycle_tag'],
